INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q16825060', 'Bussa rebellion', 'The Bussa rebellion, also known as the Boussa rebellion, was a small insurrection in the town of Bussa against the policy of indirect rule in British-ruled Nigeria in June 1915. The rebellion was triggered by the British deposition of the local Emir of Bussa, Kitoro Gani, and his replacement with a Native Administration.', 1915, 6, NULL, NULL, NULL, NULL, 'month', 'June 1915', 39, 'https://en.wikipedia.org/wiki/Bussa_rebellion'),
  ('Q16733323', 'Adubi War', 'The Adubi War (known locally as Ogun Adubi or Egba Uprising) was a conflict in June and July 1918 in the British Colony and Protectorate of Nigeria ostensibly because of the imposition of colonial taxation. Direct taxes were introduced by the colonial government along with existing forced labour obligations and fees.', 1918, 7, NULL, NULL, NULL, NULL, 'month', 'July 1918', 34, 'https://en.wikipedia.org/wiki/Adubi_War'),
  ('Q4663118', 'Somorika Women', 'The Women''s War (Igbo: Ogu Umunwanyi; Ibibio and Annang: Ekong Iban) was a period of unrest in colonial Nigeria in November 1929. The protests broke out when thousands of Igbo women from the Bende District, Umuahia and other places in Nigeria traveled to the town of Oloko to protest against the warrant chiefs, local men appointed by British colonial authorities to serve as administrative representatives and had no precedent in Igbo tradition, whom they accused of restricting the role of women in the government.', 1929, 11, NULL, NULL, NULL, NULL, 'month', 'November 1929', 52, 'https://en.wikipedia.org/wiki/Women''s_War'),
  ('Q4572480', '1966 anti-Igbo pogrom', 'The 1966 anti-Igbo pogroms were a series of widespread massacres and pogroms committed against Igbo people–and other people of southern Nigerian origin–living in northern Nigeria, starting in May 1966 and reaching its peak after 29 September 1966. Between 8,000 and 30,000 Igbos and easterners have been estimated to have been killed.', 1966, 10, NULL, NULL, NULL, NULL, 'month', 'October 1966', 41, 'https://en.wikipedia.org/wiki/1966_anti-Igbo_pogrom'),
  ('Q16205928', '1966 Nigerian coup d''etat', 'On 15 January 1966, soldiers led by Kaduna Nzeogwu and four others carried out a military putsch, killing 22 people, including Prime Minister Abubakar Tafawa Balewa and Northern Premier Ahmadu Bello, many senior politicians, senior Army officers and their wives, and sentinels on protective duty. The coup plotters attacked the cities of Kaduna, Ibadan, and Lagos while blockading the Niger and Benue River within a two-day timespan, before being overcome by loyalist forces.', 1966, 1, 16, 1966, 1, 16, 'day', '16 January 1966', 48, 'https://en.wikipedia.org/wiki/1966_Nigerian_coup_d''%C3%A9tat'),
  ('Q16908992', 'Nigerian Counter-Coup of 1966', 'The 1966 Nigerian counter-coup (also known as the "July Rematch") was the second of many military coups in Nigeria. It was masterminded by Lt.', 1966, 7, 28, NULL, NULL, NULL, 'day', '28 July 1966', 34, 'https://en.wikipedia.org/wiki/1966_Nigerian_counter-coup'),
  ('Q829875', 'Nigerian Civil War', 'The Nigerian Civil War (6 July 1967 – 15 January 1970), also known as the Biafran War, Nigeria–Biafra War, or Biafra War, was an armed conflict fought between Nigeria and the Republic of Biafra, a secessionist state that had declared its independence from Nigeria in 1967. During the war years, General Yakubu Gowon served as the head of state of Nigeria, while Biafra was led by Lieutenant Colonel Chukwuemeka "Emeka" Odumegwu Ojukwu.', 1967, 7, 6, 1970, 1, 15, 'day', '6 July 1967 – 15 January 1970', 75, 'https://en.wikipedia.org/wiki/Nigerian_Civil_War'),
  ('Q4803193', 'Asaba massacre', 'The Asaba massacre occurred on 5–7 October 1967 in Asaba, Delta State, Nigeria during the Nigerian Civil War. The massacre targeted the people of Asaba, mostly composed of Igbo people, and was perpetrated by the Nigerian Army - specifically the Second Infantry Division under the command of Murtala Muhammed.', 1967, 10, NULL, 1967, 10, 7, 'month', 'October 1967 – 7 October 1967', 39, 'https://en.wikipedia.org/wiki/Asaba_massacre'),
  ('Q16999014', 'Nigeria Airways Flight 925', 'On 20 November 1969, Nigeria Airways Flight 925, a Vickers VC10 aircraft, crashed while on approach to Lagos International Airport in Lagos, Nigeria killing all 87 people on board.', 1969, 11, 20, NULL, NULL, NULL, 'day', '20 November 1969', 45, 'https://en.wikipedia.org/wiki/Nigeria_Airways_Flight_925'),
  ('Q6364195', 'Kano air disaster', 'On 22 January 1973, a Nigeria Airways Boeing 707 crashed at Kano International Airport while attempting to land in high winds. The crash killed 176 passengers and crew.', 1973, 1, 22, NULL, NULL, NULL, 'day', '22 January 1973', 56, 'https://en.wikipedia.org/wiki/1973_Kano_Nigeria_Airways_Boeing_707_crash'),
  ('Q66741952', '1975 Nigerian coup d''état', 'The 1975 Nigerian coup d''état was a bloodless military coup which took place in Nigeria on 29 July 1975 when a faction of junior Armed Forces officers overthrew General Yakubu Gowon (who himself took power in the 1966 counter-coup). Colonel Joseph Nanven Garba announced the coup in a broadcast on Radio Nigeria (which became FRCN in 1978).', 1975, 7, 29, NULL, NULL, NULL, 'day', '29 July 1975', 37, 'https://en.wikipedia.org/wiki/1975_Nigerian_coup_d''%C3%A9tat'),
  ('Q65122502', '1985 Nigerian coup d''état', 'The 1985 Nigerian coup d''état was a military coup which took place in Nigeria on 27 August 1985 when a faction of mid-level Armed Forces officers, led by the Chief of Army Staff Major-General Ibrahim Babangida, overthrew the government of Major General Muhammadu Buhari (who himself took power in the 1983 coup d''état). Buhari was then detained in Benin City until 1988.', 1985, 8, 27, NULL, NULL, NULL, 'day', '27 August 1985', 34, 'https://en.wikipedia.org/wiki/1985_Nigerian_coup_d''%C3%A9tat'),
  ('Q98768938', '1992 Zangon Kataf crises', 'The genesis of the 1992 Zangon Kataf crises could at least be traced to the onset of the British imperial regime in the Northern Region of Nigeria, in which the Atyap people began reporting the loss of land to the Hausas. In 1922, it was reported that a large piece of land was acquired by the Emir of Zaria, Dalhatu Uthman Yero, who failed to compensate the indigenous population of the region.', 1992, 2, 6, 1992, 5, 17, 'day', '6 February 1992 – 17 May 1992', 37, 'https://en.wikipedia.org/wiki/1992_Zangon_Kataf_crises'),
  ('Q85726877', '1993 Nigerian coup d''état', 'The 1993 Nigerian coup d''état was a bloodless military coup which took place in Nigeria on 17 November 1993 when the Armed Forces, headed by Defence Minister General Sani Abacha, forced Interim President Chief Ernest Shonekan to resign. Shonekan assumed the interim presidency on 26 August 1993, succeeding General Ibrahim Babangida as head of state, in the aftermath of Babangida''s annulment of the 12 June 1993 presidential election.', 1993, 11, 17, NULL, NULL, NULL, 'day', '17 November 1993', 34, 'https://en.wikipedia.org/wiki/1993_Nigerian_coup_d''%C3%A9tat'),
  ('Q4651082', 'ADC Airlines Flight 86', 'ADC Airlines Flight 086 (ADK086) was a Nigerian domestic flight operated by ADC Airlines from Port Harcourt to Lagos. On the afternoon of 7 November 1996, the crew of the Boeing 727-231 operating the flight lost control of the aircraft while avoiding a mid-air collision on approach; the aircraft crashed inverted at a very high speed into a lagoon, killing all 144 passengers and crew on board.', 1996, 11, 7, NULL, NULL, NULL, 'day', '7 November 1996', 45, 'https://en.wikipedia.org/wiki/ADC_Airlines_Flight_086'),
  ('Q42377873', 'Herder–farmer conflicts in Nigeria', 'Across Nigeria, there are a series of disputes over arable land between Fulani herders and non-Fulani farmers. The conflicts have been especially prominent in the Middle Belt (North Central) since the return of democracy in 1999.', 1998, NULL, NULL, NULL, NULL, NULL, 'year', '1998', 43, 'https://en.wikipedia.org/wiki/Herder%E2%80%93farmer_conflicts_in_Nigeria'),
  ('Q3850911', 'Odi massacre', 'The Odi massacre was an attack carried out on 20 November 1999, by the Nigerian Armed Forces against the predominantly Ijaw town of Odi in Bayelsa State. The attack came in the context of an ongoing conflict in the Niger Delta over indigenous rights to oil resources and environmental protection.', 1999, 11, 20, NULL, NULL, NULL, 'day', '20 November 1999', 37, 'https://en.wikipedia.org/wiki/Odi_massacre'),
  ('Q615020', 'EAS Airlines Flight 4226', 'EAS Airlines Flight 4226 was a scheduled domestic passenger flight from Kano to Lagos, Nigeria. On 4 May 2002, the aircraft operating the flight overran the runway on its takeoff roll and crashed into Gwammaja Quarters, a primarily Muslim densely populated residential area, located approximately three kilometres (1.9 mi; 1.6 nmi) from the airport.', 2002, 5, 4, NULL, NULL, NULL, 'day', '4 May 2002', 48, 'https://en.wikipedia.org/wiki/EAS_Airlines_Flight_4226'),
  ('Q1202792', 'conflict in the Niger Delta', 'The current conflict in the Niger Delta first arose in the early 1990s over tensions between foreign oil corporations and a number of the Niger Delta''s minority ethnic groups who feel they are being exploited, particularly the Ogoni and the Ijaw. Ethnic and political unrest continued throughout the 1990s despite the return to democracy and the election of the Obasanjo government in 1999.', 2003, 3, 12, NULL, NULL, NULL, 'day', '12 March 2003', 60, 'https://en.wikipedia.org/wiki/Conflict_in_the_Niger_Delta'),
  ('Q3297470', 'Yelwa massacre', 'The Yelwa massacre was a series of related incidents of religious violence between Muslims and Christians which took place in Yelwa, Nigeria between February and May 2004. These incidents killed over 700 people.', 2004, NULL, NULL, NULL, NULL, NULL, 'year', '2004', 43, 'https://en.wikipedia.org/wiki/Yelwa_massacre'),
  ('Q2025205', 'Sosoliso Airlines Flight 1145', 'Sosoliso Airlines Flight 1145 (SO1145/OSL1145) was a scheduled Nigerian domestic passenger flight from Nigeria''s capital of Abuja (ABV) to Port Harcourt (PHC). At approximately 14:08 local time (13:08 UTC) on 10 December 2005, it crash-landed at Port Harcourt International Airport.', 2005, 12, 10, NULL, NULL, NULL, 'day', '10 December 2005', 58, 'https://en.wikipedia.org/wiki/Sosoliso_Airlines_Flight_1145'),
  ('Q2497839', 'Bellview Airlines Flight 210', 'Bellview Airlines Flight 210 was a scheduled Nigerian domestic passenger flight of a Boeing 737-200 airliner from Lagos to Abuja, operated by Lagos-based Bellview Airlines. On 22 October 2005, the aircraft nose-dived and crashed at high speed a few minutes after takeoff, killing all 117 people on board.', 2005, 10, 22, NULL, NULL, NULL, 'day', '22 October 2005', 50, 'https://en.wikipedia.org/wiki/Bellview_Airlines_Flight_210'),
  ('Q3048031', 'ADC Airlines Flight 53', 'ADC Airlines Flight 053 (ADK053) was a scheduled passenger flight operated by ADC Airlines from Nigeria''s capital of Abuja to Sokoto. On 29 October 2006, the Boeing 737-200 crashed onto a corn field shortly after take-off from Nnamdi Azikiwe International Airport in Abuja, killing 96 out of 105 people on board.', 2006, 10, 29, NULL, NULL, NULL, 'day', '29 October 2006', 58, 'https://en.wikipedia.org/wiki/ADC_Airlines_Flight_053'),
  ('Q2617046', '2008 Jos riots', 'The 2008 Jos riots were riots involving Christians and Muslims over the result of a local election on 28 and 29 November 2008 in Jos, a city in the North central region of Nigeria. Two days of rioting left hundreds injured and at least 761 dead.', 2008, 11, 29, NULL, NULL, NULL, 'day', '29 November 2008', 43, 'https://en.wikipedia.org/wiki/2008_Jos_riots'),
  ('Q2411274', '2009 Boko Haram uprising', 'The 2009 Boko Haram uprising was a four-day armed conflict that took place from 26 to 29 July 2009 between the Islamist militant group Boko Haram and Nigerian security forces across several states in northeastern Nigeria. Fighting broke out in Bauchi before spreading to Maiduguri, Potiskum, and Wudil.', 2009, 7, 26, 2009, 7, 29, 'day', '26 July 2009 – 29 July 2009', 39, 'https://en.wikipedia.org/wiki/2009_Boko_Haram_uprising'),
  ('Q2579041', '2009–2010 West African meningitis outbreak', 'The 2009–2010 West African meningitis outbreak was an epidemic of bacterial meningitis which occurred in Burkina Faso, Mali, Niger, and Nigeria since January 2009, an annual risk in the African meningitis belt. A total of 13,516 people have been infected with meningitis, and 931 have died.', 2009, 1, NULL, 2010, NULL, NULL, 'month', 'January 2009 – 2010', 43, 'https://en.wikipedia.org/wiki/2009%E2%80%932010_West_African_meningitis_outbreak'),
  ('Q584131', 'Dana Air Flight 992', 'Dana Air Flight 0992 was a scheduled Nigerian domestic passenger flight from Nnamdi Azikiwe International Airport to Murtala Muhammed International Airport. On 3 June 2012, the McDonnell Douglas MD-80 aircraft crashed following a dual-engine failure, killing all 153 people on board and six on the ground.', 2012, 6, 3, NULL, NULL, NULL, 'day', '3 June 2012', 62, 'https://en.wikipedia.org/wiki/Dana_Air_Flight_0992'),
  ('Q4455430', 'January 2012 Nigeria attacks', 'A series of assaults on businesses occurred in northeastern Nigeria on 5 and 6 January 2012, followed by attacks on police stations and government offices in the north on 20 January. Over 180 people were killed.', 2012, 1, 20, NULL, NULL, NULL, 'day', '20 January 2012', 39, 'https://en.wikipedia.org/wiki/January_2012_Northern_Nigeria_attacks'),
  ('Q13580335', 'Baga massacre', 'The Baga massacre began on 16 April 2013 in the village of Baga, Nigeria, in Borno State, when as many as 200 civilians were killed, hundreds wounded, and over 2,000 houses and businesses worth millions of Naira were destroyed. Refugees, civilians officials, and human rights organizations accused the Nigerian Military of carrying out the massacre; some military officials blamed the insurgent group Boko Haram.', 2013, 4, 16, 2013, 4, 17, 'day', '16 April 2013 – 17 April 2013', 41, 'https://en.wikipedia.org/wiki/2013_Baga_massacre'),
  ('Q13634281', 'Yobe State school shooting', 'On 6 July 2013, Boko Haram insurgents attacked the Government Secondary School in the village of Mamudo in Yobe State, Nigeria and killed at least 42 people. Most of the victims were students, although some staff members were also killed.', 2013, 7, 6, NULL, NULL, NULL, 'day', '6 July 2013', 39, 'https://en.wikipedia.org/wiki/Mamudo_school_massacre'),
  ('Q14972756', 'Gujba college massacre', 'On 29 September 2013, gunmen from Boko Haram entered the male dormitory in the College of Agriculture in Gujba, Yobe State, Nigeria, killing fifty students and teachers.', 2013, 9, 29, NULL, NULL, NULL, 'day', '29 September 2013', 37, 'https://en.wikipedia.org/wiki/Gujba_college_massacre'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q15728150', 'Borno Massacre', 'The Konduga massacre took place in Konduga, Borno State, Nigeria on 11 February 2014. The massacre was conducted by Boko Haram jihadis against the inhabitants of this majority-muslim town.', 2014, 2, 14, NULL, NULL, NULL, 'day', '14 February 2014', 34, 'https://en.wikipedia.org/wiki/February_2014_Konduga_massacre'),
  ('Q15731727', 'Izghe attack', 'The Izghe attack was a terrorist incident that occurred in the evening of February 15, 2014. Gunmen suspected of being members of Boko Haram entered the village of Izghe, Borno State in the early hours of the morning and murdered 105 men and 1 elderly woman.', 2014, 2, 15, NULL, NULL, NULL, 'day', '15 February 2014', 37, 'https://en.wikipedia.org/wiki/Izghe_attack'),
  ('Q15826444', 'Federal Government College attack', 'On 25 February 2014, fifty-nine boys were killed at the Federal Government College of Buni Yadi in Yobe State, Nigeria. The twenty-four buildings of the school were also burned down as a result of the attack.', 2014, 2, 25, NULL, NULL, NULL, 'day', '25 February 2014', 34, 'https://en.wikipedia.org/wiki/February_2014_Buni_Yadi_massacre'),
  ('Q16334391', 'April 2014 Abuja bombing', 'On 14 April 2014 at about 6:45 am, two bombs exploded at a crowded bus station in Nyanya, Abuja, Nigeria, killing at least 88 people and injuring at least 200. The bus station is 8 km southwest of central Federal Capital Territory.', 2014, 4, 14, NULL, NULL, NULL, 'day', '14 April 2014', 45, 'https://en.wikipedia.org/wiki/April_2014_Nyanya_bombing'),
  ('Q16914854', 'May 2014 Nigeria bombings', 'On 20 May 2014, two bombs exploded in Jos, Plateau State, Nigeria, killing at least 118 people and injuring more than 56 others. The first bombing occurred in a marketplace, and the second near a bus station.', 2014, 5, 20, NULL, NULL, NULL, 'day', '20 May 2014', 41, 'https://en.wikipedia.org/wiki/2014_Jos_bombings'),
  ('Q17136409', 'Gwoza massacre', 'The Gwoza massacre was a terrorist event that occurred on 2 June, 2014 in the Gwoza local government district, Borno State near the Nigerian-Camerounian border. Militants (presumably from Boko Haram) dressed as soldiers slaughtered hundreds of civilians in the villages of Goshe, Attagara, Agapalwa and Aganjara.', 2014, 6, 2, NULL, NULL, NULL, 'day', '2 June 2014', 37, 'https://en.wikipedia.org/wiki/June_2014_Gwoza_massacres'),
  ('Q18732673', '2015 Baga massacre', 'The 2015 Baga massacre was a series of mass killings carried out by the Boko Haram group in the north-eastern Nigerian town of Baga and its environs, in the state of Borno, between 3 January and 7 January 2015. The attack began on 3 January when Boko Haram overran a military base that was the headquarters of the Multinational Joint Task Force containing troops from Chad, Niger, and Nigeria.', 2015, 1, 7, 2015, 1, 7, 'day', '7 January 2015', 57, 'https://en.wikipedia.org/wiki/2015_Baga_massacre'),
  ('Q19517778', 'Battle of Damasak', 'Between March 9 and 17, 2015, Chadian and Nigerien soldiers recaptured the town of Damasak, located on the border between Nigeria and Niger, from Boko Haram. The bodies of over 400 civilians massacred by Boko Haram after the group''s initial capture of the town in November 2014 were discovered when the Chadians and Nigeriens seized the town.', 2015, 3, 9, 2015, 3, 17, 'day', '9 March 2015 – 17 March 2015', 39, 'https://en.wikipedia.org/wiki/Battle_of_Damasak'),
  ('Q21730772', '2015 Zaria Massacre', 'The Zaria massacre, also known as the Buhari massacre, was a massacre carried out by the Nigerian Army in Zaria, Kaduna State, Nigeria, on Saturday, 12 December 2015, against Shia Muslims, mostly members of the Islamic Movement in Nigeria (IMN). At least 1000 civilians were killed, with 347 bodies secretly buried by the Army in a mass grave.', 2015, 12, 12, NULL, NULL, NULL, 'day', '12 December 2015', 47, 'https://en.wikipedia.org/wiki/2015_Zaria_massacre'),
  ('Q22348438', '2016 Dalori attack', 'On 30 January 2016, Boko Haram militants entered the suburban town of Dalori, Borno state, Nigeria, located near Borno''s capital city, Maiduguri. Approximately 86 people were killed and upwards of 135 more injured in the attack, which is believed to have been a reprisal against the Civilian Joint Task Force (CJTF) but also comes a week after the Multinational Joint Task Force (MNJTF) announced its transition into the "resettlement and rebuilding stage" in its operation to dismantle Boko Haram.', 2016, 1, 30, NULL, NULL, NULL, 'day', '30 January 2016', 39, 'https://en.wikipedia.org/wiki/2016_Dalori_attack'),
  ('Q41603851', '2017 Benue State flooding', 'The 2017 Benue State flooding took place in September 2017 in Benue State, Nigeria. It displaced at least 100,000 people, and damaged more than 2,000 homes.', 2017, 9, NULL, NULL, NULL, NULL, 'month', 'September 2017', 45, 'https://en.wikipedia.org/wiki/2017_Benue_State_flooding'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q48811126', 'End SARS', 'End SARS, widely written as EndSARS or #EndSARS, was a decentralised social movement and series of mass protests against police brutality in Nigeria that mainly occurred in October of 2020. The movement''s slogan called for the disbandment of the Special Anti-Robbery Squad (SARS), a notorious unit of the Nigerian Police known for its long record of abuse against Nigerian citizens.', 2020, 10, NULL, NULL, NULL, NULL, 'month', 'October 2020', 57, 'https://en.wikipedia.org/wiki/End_SARS'),
  ('Q96197850', 'Gubio massacre', 'During the afternoon of 9 June 2020, a massacre occurred in a village in Gubio Local Government Area of Borno State, northeastern Nigeria. A group of gunmen on motorcycles and other vehicles attacked the village for over two hours, killing at least 81 people.', 2020, 6, 9, NULL, NULL, NULL, 'day', '9 June 2020', 34, 'https://en.wikipedia.org/wiki/Gubio_massacre'),
  ('Q100769993', 'Lekki Tollgate massacre', 'On the night of 20 October 2020, at about 6:50 p.m., members of the Nigerian Army opened fire on unarmed End SARS protesters at the Lekki toll gate (Admiralty Circle Plaza) in Lagos State, Nigeria. Amnesty International stated that at least 12 protesters were killed during the shooting.', 2020, 10, 20, NULL, NULL, NULL, 'day', '20 October 2020', 43, 'https://en.wikipedia.org/wiki/2020_Lekki_shooting'),
  ('Q102449368', 'Koshebe massacre', 'The Koshebe massacre took place on 28 November 2020 in the village of Koshebe, Nigeria, in Borno State, when as many as 110 civilians and peasant farmers were killed and six were wounded as they worked in rice fields in Koshebe village, near the northeast Nigerian city of Maiduguri. The attack was thought to be carried out by Boko Haram.', 2020, 11, 28, NULL, NULL, NULL, 'day', '28 November 2020', 39, 'https://en.wikipedia.org/wiki/Koshebe_massacre'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q107190583', 'Battle of Sambisa Forest (2021)', 'In May 2021, the Islamic State''s West Africa Province (ISWAP) launched an invasion of the Sambisa Forest in Borno State, Nigeria, which was serving as the main base of Boko Haram, a rival jihadist rebel group. Following heavy fighting, ISWAP overran the Boko Haram troops, cornering their leader Abubakar Shekau.', 2021, 5, 14, 2021, 5, 19, 'day', '14 May 2021 – 19 May 2021', 34, 'https://en.wikipedia.org/wiki/Battle_of_Sambisa_Forest_(2021)'),
  ('Q110502982', '2022 Zamfara massacres', 'From 4 to 6 January 2022, over 200 people were killed by bandits in Zamfara State, Nigeria in a series of massacres. This was the deadliest terrorist attack in recent Nigerian history.', 2022, 1, NULL, NULL, NULL, NULL, 'month', 'January 2022', 50, 'https://en.wikipedia.org/wiki/2022_Zamfara_massacres'),
  ('Q114580562', '2022 Nigeria floods', 'The 2022 Nigeria floods affected many parts of the country. From the Federal Government Data, the floods had displaced over 1.4 million people, killed over 603 people, and injured more than 2,400 people.', 2022, NULL, NULL, NULL, NULL, NULL, 'year', '2022', 41, 'https://en.wikipedia.org/wiki/2022_Nigeria_floods'),
  ('Q123010127', '2022 Bayelsa State floods', 'The 2022 Bayelsa State Flooding took place between September and November 2022 in Bayelsa State, Nigeria. It displaced at least 1.3 million people as confirmed by the Bayelsa State Emergency Management Agency.', 2022, NULL, NULL, NULL, NULL, NULL, 'year', '2022', 34, 'https://en.wikipedia.org/wiki/2022_Bayelsa_State_floods'),
  ('Q124020336', '2023 Plateau State massacres', 'A series of armed attacks occurred between 23 and 25 December 2023 in Plateau State in central Nigeria. They affected at least 17 rural communities in the Nigerian local government areas of Bokkos and Barkin Ladi, resulting in at least 200 deaths and injuries to more than 500 people as well as significant property damage.', 2023, 12, 25, NULL, NULL, NULL, 'day', '25 December 2023', 48, 'https://en.wikipedia.org/wiki/2023_Plateau_State_massacres'),
  ('Q126946653', '2024 Nigeria floods', 'Flooding in Nigeria has become a yearly occurrence that claims lives and destroys many properties. According to the Minister of Water Resources and Sanitation, Joseph Utsev, following two flood-related deaths in Abuja in July 2024, the rains have persisted, causing property and business disruption in the midst of a crippling economy where rising food costs are making matters worse for Nigerians.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 41, 'https://en.wikipedia.org/wiki/2024_Nigeria_floods'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods'),
  ('Q127387057', '2024 Lekki flood', 'On 4 July 2024, heavy rainfall caused flooding in Lekki, a city in Lagos State, Nigeria. The flooding caused significant damage to residential areas in Ibeju-Lekki and other affected locations.', 2024, 7, 4, NULL, NULL, NULL, 'day', '4 July 2024', 37, 'https://en.wikipedia.org/wiki/2024_Lekki_flood'),
  ('Q130280510', 'Borno State flooding', 'Borno State, Nigeria, faced flooding after the collapse of the Alau Dam on 10 September 2024. The Maiduguri and Jere local government areas were particularly affected: according to the National Emergency Management Agency, over 70% of the residents in Maiduguri were displaced.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 41, 'https://en.wikipedia.org/wiki/Borno_State_flooding'),
  ('Q134617311', '2025 Mokwa flood', 'On 28 May 2025, flooding caused by heavy rainfall submerged the market town of Mokwa in Niger State, Nigeria, causing severe damage. Officials said that the floods killed at least 500 people and confirmed that over 600 others were missing.', 2025, 5, NULL, NULL, NULL, NULL, 'month', 'May 2025', 43, 'https://en.wikipedia.org/wiki/2025_Mokwa_flood'),
  ('Q134895752', '2025 Nigeria floods', 'Starting in April 2025, Nigeria experienced a series of flooding events that caused property damage, fatalities, injuries and displacement. The deadliest flood was the 2025 Mokwa flood in May that killed at least 500 people.', 2025, NULL, NULL, NULL, NULL, NULL, 'year', '2025', 41, 'https://en.wikipedia.org/wiki/2025_Nigeria_floods');
